# Generated by test-lab — blind adversarial evaluation
"""Scanner verdicts are terminal: complete is never re-evaluated by a second
model call. The scanner-dispatched retrieval path must not invoke the legacy
stage-1 readiness resolver."""

from __future__ import annotations

import pytest

from live_evidence.config import AppSettings, InterviewProfile
from live_evidence.coordinator import EvidenceCoordinator
from live_evidence.trigger import TriggerDecision
from live_evidence.persistence import SessionJournal
from live_evidence.state import RuntimeState


class _EmptyResult:
    ok = True
    detail = "stub"
    latency_ms = 1
    sources: list = []


@pytest.mark.asyncio
async def test_scanner_complete_skips_readiness_resolver(tmp_path, monkeypatch) -> None:
    monkeypatch.setenv("LIVE_EVIDENCE_DATA_DIR", str(tmp_path))
    settings = AppSettings.from_env()
    profile = InterviewProfile(name="terminal-test")
    state = RuntimeState(settings, profile)
    await state.start_session(consent_confirmed=True)
    coordinator = EvidenceCoordinator(settings, profile, state, SessionJournal(tmp_path))

    async def _fail_resolver(*args, **kwargs):  # noqa: ANN002, ANN003
        raise AssertionError("stage-1 resolver must not run for scanner_complete")

    async def _empty_retrieve(*args, **kwargs):  # noqa: ANN002, ANN003
        return _EmptyResult()

    async def _suppress_surface(query, thread, ranked, **kwargs):  # noqa: ANN003
        return ranked, False  # exit before solver; resolver-skip already proven

    monkeypatch.setattr(coordinator, "_resolve_readiness", _fail_resolver)
    monkeypatch.setattr(coordinator._memory, "retrieve", _empty_retrieve)
    monkeypatch.setattr(coordinator._ripgrep, "retrieve", _empty_retrieve)
    monkeypatch.setattr(coordinator, "_surface_order", _suppress_surface)

    question_id, revision = await state.adopt_question("q_scanner_terminal", "Which nodes may run in parallel?")
    decision = TriggerDecision(
        event_id=question_id,
        query="Which nodes may run in parallel?",
        thread="Which nodes may run in parallel?"[:60],
        reason="scanner_complete",
        source_event_ids=("evt-1",),
        candidate_fingerprint=None,
    )
    # Raises AssertionError if the resolver is consulted.
    await coordinator._retrieve(
        decision,
        question_id,
        revision,
        session_id=state.session_id(),
        policy_digest=state.session_policy_digest(),
    )


@pytest.mark.asyncio
async def test_legacy_path_still_consults_resolver(tmp_path, monkeypatch) -> None:
    monkeypatch.setenv("LIVE_EVIDENCE_DATA_DIR", str(tmp_path))
    settings = AppSettings.from_env()
    profile = InterviewProfile(name="terminal-test")
    state = RuntimeState(settings, profile)
    await state.start_session(consent_confirmed=True)
    coordinator = EvidenceCoordinator(settings, profile, state, SessionJournal(tmp_path))

    calls: list[str] = []

    async def _tracking_resolver(query, ledger=None):  # noqa: ANN001
        calls.append(query)
        return None

    async def _empty_retrieve(*args, **kwargs):  # noqa: ANN002, ANN003
        return _EmptyResult()

    async def _suppress_surface(query, thread, ranked, **kwargs):  # noqa: ANN003
        return ranked, False

    monkeypatch.setattr(coordinator, "_resolve_readiness", _tracking_resolver)
    monkeypatch.setattr(coordinator._memory, "retrieve", _empty_retrieve)
    monkeypatch.setattr(coordinator._ripgrep, "retrieve", _empty_retrieve)
    monkeypatch.setattr(coordinator, "_surface_order", _suppress_surface)

    question_id, revision = await state.adopt_question("q_legacy", "What is the deploy cadence?")
    decision = TriggerDecision(
        event_id=question_id,
        query="What is the deploy cadence?",
        thread="What is the deploy cadence?"[:60],
        reason="question",
        source_event_ids=("evt-2",),
        candidate_fingerprint=None,
    )
    await coordinator._retrieve(
        decision,
        question_id,
        revision,
        session_id=state.session_id(),
        policy_digest=state.session_policy_digest(),
    )
    assert calls == ["What is the deploy cadence?"]
